INSERT INTO word_examples (example_id, word_id, german, translation) VALUES
  ('b0000001-0000-0000-0000-000000000001', 'a0000001-0000-0000-0000-000000000004', 'Ich bin Student.', '我是学生。'),
  ('b0000001-0000-0000-0000-000000000002', 'a0000001-0000-0000-0000-000000000004', 'Du bist sehr nett.', '你很友好。'),
  ('b0000001-0000-0000-0000-000000000003', 'a0000001-0000-0000-0000-000000000005', 'Ich habe ein Buch.', '我有一本书。'),
  ('b0000001-0000-0000-0000-000000000004', 'a0000001-0000-0000-0000-000000000005', 'Wir haben Zeit.', '我们有时间。'),
  ('b0000001-0000-0000-0000-000000000005', 'a0000001-0000-0000-0000-000000000006', 'Ich gehe zur Schule.', '我去学校。'),
  ('b0000001-0000-0000-0000-000000000006', 'a0000001-0000-0000-0000-000000000007', 'Woher kommen Sie?', '您来自哪里？'),
  ('b0000001-0000-0000-0000-000000000007', 'a0000001-0000-0000-0000-000000000010', 'Ich lerne Deutsch.', '我学德语。'),
  ('b0000001-0000-0000-0000-000000000008', 'a0000001-0000-0000-0000-000000000011', 'Das Haus ist groß.', '这个房子很大。'),
  ('b0000001-0000-0000-0000-000000000009', 'a0000001-0000-0000-0000-000000000012', 'Die Schule ist neu.', '这所学校是新的。'),
  ('b0000001-0000-0000-0000-000000000010', 'a0000001-0000-0000-0000-000000000013', 'Ich lese ein Buch.', '我在读一本书。')
INSERT INTO grammar_points (grammar_id, title, rule_text, difficulty, exercise_available, created_at, external_id, book, lektion) VALUES
  ('c0000001-0000-0000-0000-000000000001', '动词 sein 的变位', '动词 sein（是）在现在时中的变位：ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind。', '初级', 1, '2026-01-01T00:00:00.000Z', 'G001', 1, 1),
  ('c0000001-0000-0000-0000-000000000002', '动词 haben 的变位', '动词 haben（有）在现在时中的变位：ich habe, du hast, er/sie/es hat, wir haben, ihr habt, sie/Sie haben。', '初级', 1, '2026-01-01T00:00:00.000Z', 'G002', 1, 1),
  ('c0000001-0000-0000-0000-000000000003', '定冠词 der/die/das', '德语定冠词有三性：der（阳性）、die（阴性）、das（中性），复数都用 die。', '初级', 1, '2026-01-01T00:00:00.000Z', 'G003', 1, 2),
  ('c0000001-0000-0000-0000-000000000004', '人称代词', '德语人称代词：ich（我）, du（你）, er（他）, sie（她）, es（它）, wir（我们）, ihr（你们）, sie（他们）, Sie（您）。', '初级', 1, '2026-01-01T00:00:00.000Z', 'G004', 1, 2),
  ('c0000001-0000-0000-0000-000000000005', '规则动词现在时变位', '规则动词现在时变位：去掉 -en 后加人称词尾。如 machen: ich mache, du machst, er macht, wir machen, ihr macht, sie machen。', '初级', 1, '2026-01-01T00:00:00.000Z', 'G005', 1, 3),
  ('c0000001-0000-0000-0000-000000000006', 'W疑问句', 'W疑问词：was（什么）, wer（谁）, wo（哪里）, wann（何时）, warum（为什么）, wie（怎样）, wohin（去哪里）, woher（从哪里）。', '初级', 1, '2026-01-01T00:00:00.000Z', 'G006', 1, 3),
  ('c0000001-0000-0000-0000-000000000007', '情态动词 können', '情态动词 können（能够）变位：ich kann, du kannst, er kann, wir können, ihr könnt, sie können。', '初级', 1, '2026-01-01T00:00:00.000Z', 'G007', 1, 4),
  ('c0000001-0000-0000-0000-000000000008', '名词的复数形式', '德语名词复数形式多样，常见有加 -e（Buch→Bücher）、加 -er、加 -n、加 -s、不变（Lehrer→Lehrer）等。', '初级', 1, '2026-01-01T00:00:00.000Z', 'G008', 1, 4),
  ('c0000001-0000-0000-0000-000000000009', '形容词基本用法', '形容词作表语时不变化：Das Haus ist groß。形容词作定语时需加词尾：ein großes Haus。', '中级', 1, '2026-01-01T00:00:00.000Z', 'G009', 2, 5),
  ('c0000001-0000-0000-0000-000000000010', '过去时 Präteritum', '过去时用于叙述。规则动词：machte。sein 的过去时：war, warst, war, waren, wart, waren。', '中级', 1, '2026-01-01T00:00:00.000Z', 'G010', 2, 5)
INSERT INTO grammar_examples (example_id, grammar_id, german, translation) VALUES
  ('d0000001-0000-0000-0000-000000000001', 'c0000001-0000-0000-0000-000000000001', 'Ich bin Student.', '我是学生。'),
  ('d0000001-0000-0000-0000-000000000002', 'c0000001-0000-0000-0000-000000000001', 'Wir sind hier.', '我们在这里。'),
  ('d0000001-0000-0000-0000-000000000003', 'c0000001-0000-0000-0000-000000000002', 'Ich habe ein Auto.', '我有一辆车。'),
  ('d0000001-0000-0000-0000-000000000004', 'c0000001-0000-0000-0000-000000000002', 'Er hat keine Zeit.', '他没有时间。'),
  ('d0000001-0000-0000-0000-000000000005', 'c0000001-0000-0000-0000-000000000003', 'der Tisch, die Lampe, das Buch', '这张桌子（阳），这盏灯（阴），这本书（中）'),
  ('d0000001-0000-0000-0000-000000000006', 'c0000001-0000-0000-0000-000000000004', 'Ich heiße Anna.', '我叫安娜。'),
  ('d0000001-0000-0000-0000-000000000007', 'c0000001-0000-0000-0000-000000000005', 'Ich lerne Deutsch.', '我学德语。'),
  ('d0000001-0000-0000-0000-000000000008', 'c0000001-0000-0000-0000-000000000006', 'Wo wohnst du?', '你住在哪里？'),
  ('d0000001-0000-0000-0000-000000000009', 'c0000001-0000-0000-0000-000000000007', 'Ich kann Deutsch sprechen.', '我会说德语。'),
  ('d0000001-0000-0000-0000-000000000010', 'c0000001-0000-0000-0000-000000000008', 'das Buch → die Bücher', '书 → 书（复数）'),
  ('d0000001-0000-0000-0000-000000000011', 'c0000001-0000-0000-0000-000000000009', 'ein großes Haus', '一栋大房子'),
  ('d0000001-0000-0000-0000-000000000012', 'c0000001-0000-0000-0000-000000000010', 'Ich war in Berlin.', '我曾在柏林。')
INSERT INTO grammar_exercises (exercise_id, grammar_id, type, question, answer, explanation, difficulty, created_at, external_id, grammar_external_id) VALUES
  ('e0000001-0000-0000-0000-000000000001', 'c0000001-0000-0000-0000-000000000001', 'G1', 'Ich ___ Student. (sein)', 'bin', '第一人称 ich 对应 bin。', '初级', '2026-01-01T00:00:00.000Z', 'E001', 'G001'),
  ('e0000001-0000-0000-0000-000000000002', 'c0000001-0000-0000-0000-000000000001', 'G1', 'Du ___ sehr nett. (sein)', 'bist', '第二人称 du 对应 bist。', '初级', '2026-01-01T00:00:00.000Z', 'E002', 'G001'),
  ('e0000001-0000-0000-0000-000000000003', 'c0000001-0000-0000-0000-000000000001', 'G1', 'Wir ___ hier. (sein)', 'sind', '第一人称复数 wir 对应 sind。', '初级', '2026-01-01T00:00:00.000Z', 'E003', 'G001'),
  ('e0000001-0000-0000-0000-000000000004', 'c0000001-0000-0000-0000-000000000002', 'G1', 'Ich ___ ein Buch. (haben)', 'habe', '第一人称 ich 对应 habe。', '初级', '2026-01-01T00:00:00.000Z', 'E004', 'G002'),
  ('e0000001-0000-0000-0000-000000000005', 'c0000001-0000-0000-0000-000000000002', 'G1', 'Er ___ keine Zeit. (haben)', 'hat', '第三人称 er 对应 hat。', '初级', '2026-01-01T00:00:00.000Z', 'E005', 'G002'),
  ('e0000001-0000-0000-0000-000000000006', 'c0000001-0000-0000-0000-000000000003', 'G2', '选择正确的冠词：___ Tisch (桌子)', 'der', 'Tisch 是阳性名词，用 der。', '初级', '2026-01-01T00:00:00.000Z', 'E006', 'G003'),
  ('e0000001-0000-0000-0000-000000000007', 'c0000001-0000-0000-0000-000000000003', 'G2', '选择正确的冠词：___ Lampe (灯)', 'die', 'Lampe 是阴性名词，用 die。', '初级', '2026-01-01T00:00:00.000Z', 'E007', 'G003'),
  ('e0000001-0000-0000-0000-000000000008', 'c0000001-0000-0000-0000-000000000003', 'G2', '选择正确的冠词：___ Buch (书)', 'das', 'Buch 是中性名词，用 das。', '初级', '2026-01-01T00:00:00.000Z', 'E008', 'G003'),
  ('e0000001-0000-0000-0000-000000000009', 'c0000001-0000-0000-0000-000000000005', 'G1', 'Ich ___ Deutsch. (lernen)', 'lerne', '规则动词 lernen：ich 对应 lerne。', '初级', '2026-01-01T00:00:00.000Z', 'E009', 'G005'),
  ('e0000001-0000-0000-0000-000000000010', 'c0000001-0000-0000-0000-000000000005', 'G1', 'Du ___ Deutsch. (lernen)', 'lernst', '规则动词 lernen：du 对应 lernst。', '初级', '2026-01-01T00:00:00.000Z', 'E010', 'G005'),
  ('e0000001-0000-0000-0000-000000000011', 'c0000001-0000-0000-0000-000000000007', 'G1', 'Ich ___ Deutsch sprechen. (können)', 'kann', '情态动词 können：ich 对应 kann。', '初级', '2026-01-01T00:00:00.000Z', 'E011', 'G007'),
  ('e0000001-0000-0000-0000-000000000012', 'c0000001-0000-0000-0000-000000000007', 'G1', 'Wir ___ gut kochen. (können)', 'können', '情态动词 können：wir 对应 können。', '初级', '2026-01-01T00:00:00.000Z', 'E012', 'G007'),
  ('e0000001-0000-0000-0000-000000000013', 'c0000001-0000-0000-0000-000000000008', 'G2', 'das Buch 的复数是？', 'die Bücher', 'Buch 的复数为 Bücher，复数冠词用 die。', '初级', '2026-01-01T00:00:00.000Z', 'E013', 'G008'),
  ('e0000001-0000-0000-0000-000000000014', 'c0000001-0000-0000-0000-000000000008', 'G2', 'das Haus 的复数是？', 'die Häuser', 'Haus 的复数为 Häuser，复数冠词用 die。', '初级', '2026-01-01T00:00:00.000Z', 'E014', 'G008'),
  ('e0000001-0000-0000-0000-000000000015', 'c0000001-0000-0000-0000-000000000010', 'G1', 'Ich ___ in Berlin. (sein, 过去时)', 'war', 'sein 的过去时：ich 对应 war。', '中级', '2026-01-01T00:00:00.000Z', 'E015', 'G010'),
  ('e0000001-0000-0000-0000-000000000016', 'c0000001-0000-0000-0000-000000000010', 'G1', 'Wir ___ müde. (sein, 过去时)', 'waren', 'sein 的过去时：wir 对应 waren。', '中级', '2026-01-01T00:00:00.000Z', 'E016', 'G010'),
  ('e0000001-0000-0000-0000-000000000017', 'c0000001-0000-0000-0000-000000000004', 'G2', '___ heiße Anna. (填人称代词)', 'Ich', '第一人称单数用 Ich。', '初级', '2026-01-01T00:00:00.000Z', 'E017', 'G004'),
  ('e0000001-0000-0000-0000-000000000018', 'c0000001-0000-0000-0000-000000000004', 'G2', 'Wie heißt ___? (对男姓陌生人尊称)', 'Sie', '尊称用 Sie。', '初级', '2026-01-01T00:00:00.000Z', 'E018', 'G004'),
  ('e0000001-0000-0000-0000-000000000019', 'c0000001-0000-0000-0000-000000000006', 'G2', '___ wohnst du? (问住在哪里)', 'Wo', '问地点用 Wo。', '初级', '2026-01-01T00:00:00.000Z', 'E019', 'G006'),
  ('e0000001-0000-0000-0000-000000000020', 'c0000001-0000-0000-0000-000000000006', 'G2', '___ heißt du? (问叫什么名字)', 'Wie', '问方式/名称用 Wie。', '初级', '2026-01-01T00:00:00.000Z', 'E020', 'G006'),
  ('e0000001-0000-0000-0000-000000000021', 'c0000001-0000-0000-0000-000000000009', 'G2', 'Das Haus ist ___. (groß)', 'groß', '形容词作表语不变化。', '中级', '2026-01-01T00:00:00.000Z', 'E021', 'G009'),
  ('e0000001-0000-0000-0000-000000000022', 'c0000001-0000-0000-0000-000000000009', 'G2', 'ein ___ Haus (groß)', 'großes', '形容词作定语加词尾 -es。', '中级', '2026-01-01T00:00:00.000Z', 'E022', 'G009')
